function drawBarcodes(){document.querySelectorAll('.barcode').forEach(svg=>{const digits=svg.dataset.digits||'1234567890123456';const values=digits.match(/.{2}/g).map(Number);let sum=105;values.forEach((v,i)=>sum+=v*(i+1));let x=12,rects='';[105,...values,sum%103,106].forEach(c=>{let black=true;for(const w of C128[c]){if(black)rects+=`<rect x="${x}" y="0" width="${w}" height="40"/>`;x+=Number(w);black=!black;}});svg.setAttribute('viewBox',`0 0 ${x+12} 40`);svg.setAttribute('preserveAspectRatio','none');svg.innerHTML=rects;});}
